const PR6=[{label:"Ví dụ: Số byte của mảng và vector",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a[1000];\n    long long b[1000];\n    vector<int> v(1000);\n    a[0] = 1;\n    b[0] = 2;\n    cout << sizeof(a) << \" \" << sizeof(b) << \" \" << v.size() * sizeof(int) << \"\\n\";\n    return 0;\n}",py:{label:"Ví dụ: Số byte của list",code:"import sys\na = [0] * 1000\nb = [10 ** 12] * 1000\nc = list(range(1000))\nprint(sys.getsizeof(a), sys.getsizeof(b), sys.getsizeof(c))\nprint(sys.getsizeof(0), sys.getsizeof(10 ** 12), sys.getsizeof(1.5))",note:"List của Python không chứa số trực tiếp mà chứa 1000 “con trỏ” 8 byte, cộng 56 byte phần đầu: 8056 byte dù phần tử là số nhỏ hay lớn. Bản thân mỗi số nguyên là một đối tượng riêng khoảng 28 byte, nên list(range(1000)) thật ra tốn khoảng 8 KB + 28 KB."},cs:{label:"Ví dụ: Số byte của mảng",code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = new int[1000];\n        long[] b = new long[1000];\n        char[] c = new char[1000];\n        a[0] = 1;\n        b[0] = 2;\n        Console.WriteLine(a.Length * sizeof(int) + \" \" + b.Length * sizeof(long) + \" \" + c.Length * sizeof(char));\n    }\n}",note:"sizeof(kiểu) cho số byte của một phần tử: int 4, long 8, double 8, char 2 (C# lưu chữ theo UTF-16), bool 1. Mỗi mảng còn tốn thêm khoảng 24 byte thông tin đầu (độ dài, kiểu)."}},{label:"Ví dụ: Đọc từng số, bộ nhớ O(1)",input:"6\n4 9 1 7 3 8",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    long long tong = 0;\n    int lon = 0;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        tong += x;\n        if (i == 0 || x > lon) lon = x;\n    }\n    cout << tong << \" \" << lon << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["i","x","tong","lon"]}],py:{label:"Ví dụ: Không lưu cả dãy",code:"n = int(input())\ntong = 0\nlon = None\nfor x in map(int, input().split()):\n    tong += x\n    if lon is None or x > lon:\n        lon = x\nprint(tong, lon)",viz:[{type:"vars",names:["x","tong","lon"]}],note:"Duyệt thẳng map(int, …) mà không tạo list: chỉ vài biến được giữ lại. (Chuỗi của dòng nhập vẫn nằm trong bộ nhớ; với dữ liệu thật lớn có thể đọc từng dòng bằng sys.stdin.)"},cs:{label:"Ví dụ: Không lưu dãy số",code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        string[] s = Console.ReadLine().Split();\n        long tong = 0;\n        int lon = 0;\n        for (int i = 0; i < n; i++)\n        {\n            int x = int.Parse(s[i]);\n            tong += x;\n            if (i == 0 || x > lon) lon = x;\n        }\n        Console.WriteLine(tong + \" \" + lon);\n    }\n}",note:"Đổi từng chuỗi sang số khi cần, không tạo mảng int: phần tính toán chỉ giữ vài biến. (Mảng chuỗi s của dòng nhập vẫn nằm trong bộ nhớ; với dữ liệu thật lớn có thể đọc từng dòng.)"}},{label:"Ví dụ: Tính sẵn bảng Fibonacci",input:"4\n10 20 30 50",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    const int MOD = 1000000007;\n    vector<long long> f(51);\n    f[0] = 0;\n    f[1] = 1;\n    for (int i = 2; i <= 50; i++) f[i] = (f[i - 1] + f[i - 2]) % MOD;\n    int q;\n    cin >> q;\n    for (int t = 0; t < q; t++) {\n        int k;\n        cin >> k;\n        cout << f[k] << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"f",max:24}],py:{code:"MOD = 1000000007\nf = [0] * 51\nf[0] = 0\nf[1] = 1\nfor i in range(2, 51):\n    f[i] = (f[i - 1] + f[i - 2]) % MOD\nq = int(input())\nfor k in map(int, input().split()):\n    print(f[k])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const int MOD = 1000000007;\n        long[] f = new long[51];\n        f[0] = 0;\n        f[1] = 1;\n        for (int i = 2; i <= 50; i++) f[i] = (f[i - 1] + f[i - 2]) % MOD;\n        int q = int.Parse(Console.ReadLine());\n        string[] s = Console.ReadLine().Split();\n        for (int t = 0; t < q; t++)\n        {\n            int k = int.Parse(s[t]);\n            Console.WriteLine(f[k]);\n        }\n    }\n}"}},{label:"Ví dụ: Đệ quy tốn bộ nhớ ngăn xếp",input:"",code:"#include <iostream>\nusing namespace std;\n\nlong long tong(int n) {\n    if (n == 0) return 0;\n    return n + tong(n - 1);\n}\n\nint main() {\n    cout << tong(5) << \"\\n\";\n    return 0;\n}",py:{code:"def tong(n):\n    if n == 0:\n        return 0\n    return n + tong(n - 1)\n\nprint(tong(5))",note:"Mỗi lời gọi tong(n) chiếm một khung trên ngăn xếp tới khi trả về: sâu n tầng là O(n) bộ nhớ. Python mặc định chỉ cho sâu khoảng 1000 tầng (sys.setrecursionlimit để tăng)."},cs:{code:"using System;\n\nclass Program\n{\n    static long Tong(int n)\n    {\n        if (n == 0) return 0;\n        return n + Tong(n - 1);\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Tong(5));\n    }\n}",note:"Mỗi lời gọi Tong(n) chiếm một khung trên ngăn xếp tới khi trả về: sâu n tầng là O(n) bộ nhớ. Ngăn xếp của C# thường chỉ 1–8 MB: đệ quy sâu vài chục nghìn tầng có thể làm chương trình dừng với lỗi Stack overflow."}}];
