makeEx2(document.getElementById("ex-l6"),sim6,[{t:"Bảng có vừa bộ nhớ không?",d:"Đầu vào: n, m (1 ≤ n, m ≤ 10^6). Một chương trình khai báo bảng int a[n][m] (mỗi int 4 byte). Đầu ra: dòng 1 là số byte của bảng; dòng 2 là OK nếu số byte không quá 256 MB (256 × 1024 × 1024 byte), ngược lại QUA BO NHO.",tests:[{in:"1000 1000",out:"4000000\nOK"},{in:"10000 10000",out:"400000000\nQUA BO NHO"},{in:"8192 8192",out:"268435456\nOK"},{in:"1000000 1000000",out:"4000000000000\nQUA BO NHO"},{in:"1 1",out:"4\nOK"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n, m;\n    cin >> n >> m;\n    // số byte = n * m * 4; so với 256 * 1024 * 1024\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\n# số byte = n * m * 4; so với 256 * 1024 * 1024",hints:["Bài tính bộ nhớ của một bảng int trong C/C++ (4 byte mỗi ô); với Python chỉ cần tính số.","256 MB = 256 · 1024 · 1024 = 268 435 456 byte."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        long n = long.Parse(s[0]), m = long.Parse(s[1]);\n        // số byte = n * m * 4; so với 256 * 1024 * 1024\n    }\n}",hints:["Số byte có thể tới 4 · 10^12: dùng long cho n, m và kết quả.","256 MB = 256 · 1024 · 1024 = 268 435 456 byte; viết 256L để phép nhân thực hiện trên long."]}},{t:"Độ phức tạp cần đạt",d:"Đầu vào: n (1 ≤ n ≤ 10^18), giới hạn của một đề bài chạy trong 1 giây. Theo bảng ở mục 6.2, in độ phức tạp lớn nhất chấp nhận được: O(n!) nếu n ≤ 11; O(2^n) nếu n ≤ 25; O(n^3) nếu n ≤ 500; O(n^2) nếu n ≤ 5000; O(nlogn) nếu n ≤ 1000000; O(n) nếu n ≤ 100000000; còn lại O(logn).",tests:[{in:"10",out:"O(n!)"},{in:"20",out:"O(2^n)"},{in:"300",out:"O(n^3)"},{in:"5000",out:"O(n^2)"},{in:"100000",out:"O(nlogn)"},{in:"50000000",out:"O(n)"},{in:"1000000000000000000",out:"O(logn)"},{in:"25",out:"O(2^n)"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    // xét các ngưỡng từ nhỏ tới lớn\n    return 0;\n}",py:{start:"n = int(input())\n# xét các ngưỡng từ nhỏ tới lớn",hints:["Dùng chuỗi if … elif theo thứ tự ngưỡng tăng dần: điều kiện đầu tiên đúng sẽ quyết định."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        // xét các ngưỡng từ nhỏ tới lớn\n    }\n}",hints:["Dùng chuỗi if … else if theo thứ tự ngưỡng tăng dần: điều kiện đầu tiên đúng sẽ quyết định.","n tới 10^18 nên đọc bằng long.Parse."]}},{t:"Fibonacci nhiều câu hỏi",d:"Dãy F: F(0) = 0, F(1) = 1, F(k) = F(k−1) + F(k−2). Đầu vào: q (1 ≤ q ≤ 10^5) rồi q số k (0 ≤ k ≤ 1000). Đầu ra: với mỗi k, in F(k) chia lấy dư cho 1000000007, mỗi số một dòng. Tính lại từ đầu cho mỗi câu hỏi là quá chậm khi q lớn.",tests:[{in:"4\n0 1 10 50",out:"0\n1\n55\n586268941"},{in:"1\n1000",out:"517691607"},{in:"3\n2 2 2",out:"1\n1\n1"},{in:"2\n100 3",out:"687995182\n2"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int q;\n    cin >> q;\n    // tính sẵn F(0..1000) một lần, rồi trả lời từng câu hỏi\n    return 0;\n}",perf:{gen:q=>q+"\n"+Array(q).fill(1000).join(" "),ns:[300,1200,4800],need:"n",limit:q=>9*q+12000,why:"Tính lại dãy từ đầu cho mỗi câu hỏi tốn khoảng 1000 bước × q câu hỏi. Hãy tính sẵn bảng một lần."},py:{start:"q = int(input())\nks = list(map(int, input().split()))\n# tính sẵn F(0..1000) một lần, rồi trả lời từng câu hỏi",hints:["Tính bảng f[0..1000] một lần trước khi đọc câu hỏi: khoảng 1000 bước.","Mỗi câu hỏi chỉ in f[k]: tổng O(1000 + q) thay vì O(q · 1000).","Lấy % MOD sau mỗi phép cộng để số không phình to (số nguyên Python lớn tùy ý nhưng càng lớn càng tính chậm)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int q = int.Parse(Console.ReadLine());\n        int[] k = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // tính sẵn F(0..1000) một lần, rồi trả lời từng câu hỏi\n    }\n}",hints:["Tính bảng f[0..1000] một lần trước khi trả lời: khoảng 1000 bước.","Mỗi câu hỏi chỉ lấy f[k]: tổng O(1000 + q) thay vì O(q · 1000).","In nhiều dòng: gom vào StringBuilder rồi in một lần nhanh hơn gọi Console.WriteLine q lần. Lấy % MOD sau mỗi phép cộng để số không vượt long."]}}]);

